const db = getFirestore();

const tonsMaiores = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const tonsMenores = ['Cm', 'C#m', 'Dm', 'D#m', 'Em', 'Fm', 'F#m', 'Gm', 'G#m', 'Am', 'A#m', 'Bm'];
const allTons = [...tonsMaiores, ...tonsMenores];

const cardGradients = [
  ['#151C3C', '#222047', '#2D2146'],
  ['#111D34', '#1F2948', '#243657'],
  ['#211B3D', '#24254A', '#18364A'],
];

function PressableScale({ children, onPress, style, disabled }: any) {
  const scale = React.useRef(new Animated.Value(1)).current;

  return (
    <TouchableOpacity
      activeOpacity={0.86}
      disabled={disabled}
      onPress={onPress}
      onPressIn={() => scale.setValue(0.97)}
      onPressOut={() => {
        Animated.spring(scale, {
          toValue: 1,
          useNativeDriver: true,
          friction: 3,
          tension: 40,
        }).start();
      }}
      style={style}
    >
      <Animated.View style={{ transform: [{ scale }] }}>{children}</Animated.View>
    </TouchableOpacity>
  );
}

function GradientButton({ children, onPress, disabled, variant = 'primary', style }: any) {
  const colors = variant === 'secondary'
    ? ['#67E8F9', '#38BDF8']
    : variant === 'success'
      ? ['#43E97B', '#16A34A']
      : ['#FFB84D', '#FF7A3D'];

  return (
    <PressableScale onPress={onPress} disabled={disabled} style={[styles.buttonWrap, style]}>
      <LinearGradient colors={colors} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={[styles.gradientButton, disabled && styles.disabledButton]}>
        <Text style={styles.gradientButtonText}>{children}</Text>
      </LinearGradient>
    </PressableScale>
  );
}

const DetalheRepertorio = () => {
  const route = useRoute();
  const navigation = useNavigation();
  const { repertorio } = route.params as any;

  const [titulo, setTitulo] = useState(repertorio.titulo || '');
  const [data, setData] = useState(repertorio.data || '');
  const [responsavel, setResponsavel] = useState(repertorio.responsavel || '');
  const [musicas, setMusicas] = useState(repertorio.musicas || []);
  const [editando, setEditando] = useState(false);
  const [salvando, setSalvando] = useState(false);

  const [novaNome, setNovaNome] = useState('');
  const [novaTom, setNovaTom] = useState('C');
  const [novaLinkLetra, setNovaLinkLetra] = useState('');
  const [novaLinkYoutube, setNovaLinkYoutube] = useState('');
  const [tomIndexes, setTomIndexes] = useState(
    (repertorio.musicas || []).map((m: any) => {
      const idx = allTons.indexOf(m.tom);
      return idx >= 0 ? idx : 0;
    })
  );

  const handleChangeMusica = (idx: number, field: string, value: any) => {
    setMusicas(prev =>
      prev.map((m: any, i: number) => (i === idx ? { ...m, [field]: value } : m))
    );
    if (field === 'tom') {
      setTomIndexes(prev => prev.map((v, i) => (i === idx ? allTons.indexOf(value) : v)));
    }
  };

  const handleAdicionarMusica = () => {
    if (!novaNome.trim()) {
      Alert.alert('Atencao', 'Informe o nome da musica.');
      return;
    }
    setMusicas(prev => [
      ...prev,
      { nome: novaNome, tom: novaTom, linkLetra: novaLinkLetra, linkYoutube: novaLinkYoutube },
    ]);
    setTomIndexes(prev => [...prev, allTons.indexOf(novaTom)]);
    setNovaNome('');
    setNovaTom('C');
    setNovaLinkLetra('');
    setNovaLinkYoutube('');
  };

  const handleExcluirMusica = (index: number) => {
    const musica = musicas[index];
    confirmAction({
      title: 'Excluir musica',
      message: `Deseja realmente excluir "${musica?.nome || `Musica ${index + 1}`}" deste repertorio?`,
      onConfirm: () => {
        setMusicas(prev => prev.filter((_: any, i: number) => i !== index));
        setTomIndexes(prev => prev.filter((_: number, i: number) => i !== index));
      },
    });
  };

  const handleSalvar = async () => {
    setSalvando(true);
    try {
      await updateDoc(doc(db, 'repertorios', repertorio.id), { titulo, data, responsavel, musicas });
      Alert.alert('Sucesso', 'Repertorio atualizado!');
      setEditando(false);

      const metaRef = doc(db, 'meta', 'repertorios');
      try {
        await updateDoc(metaRef, { newCount: increment(1), lastUpdated: new Date() });
      } catch {
        await setDoc(metaRef, { newCount: 1, lastUpdated: new Date() }, { merge: true });
      }

      try {
        const cur = await AsyncStorage.getItem('nova_repertorio');
        const num = cur ? parseInt(cur, 10) || 0 : 0;
        const novo = num + 1;
        await AsyncStorage.setItem('nova_repertorio', String(novo));
        await Notifications.setBadgeCountAsync(novo);
      } catch (e) {
        console.log('Erro ao setar contador/badge local depois de editar repertorio', e);
      }
    } catch {
      Alert.alert('Erro', 'Nao foi possivel atualizar o repertorio.');
    } finally {
      setSalvando(false);
    }
  };

  const abrirLink = (link?: string) => {
    if (link) Linking.openURL(link);
  };

  const renderCampoResumo = (
    icon: any,
    label: string,
    value: string,
    onChangeText: (value: string) => void,
    placeholder: string
  ) => (
    <LinearGradient colors={['#FFB84D', '#43E97B', '#46D7FF']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.summaryBorder}>
      <LinearGradient colors={['#151C3C', '#222047']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.summaryCard}>
        <View style={styles.summaryIcon}>
          <MaterialCommunityIcons name={icon} size={22} color="#111827" />
        </View>
        <View style={styles.summaryContent}>
          <Text style={styles.summaryLabel}>{label}</Text>
          <TextInput
            style={[styles.summaryInput, !editando && styles.inputReadOnly]}
            value={value}
            editable={editando}
            onChangeText={onChangeText}
            placeholder={placeholder}
            placeholderTextColor="#90caf9"
          />
        </View>
      </LinearGradient>
    </LinearGradient>
  );

  return (
    <LinearGradient colors={['#0B1630', '#161934', '#241A3D']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.bg}>
      <ScrollView contentContainerStyle={styles.container} keyboardShouldPersistTaps="handled">
        <View style={styles.header}>
          <PressableScale style={styles.headerIconBtn} onPress={() => navigation.navigate('Inicio')}>
            <MaterialCommunityIcons name="home-variant-outline" size={24} color="#43E97B" />
          </PressableScale>
          <View style={styles.headerTitleWrap}>
            <View style={styles.headerTitleIcon}>
              <MaterialCommunityIcons name="headphones" size={23} color="#111827" />
            </View>
            <Text style={styles.headerTitle}>Meu Repertorio</Text>
          </View>
          <PressableScale style={styles.headerIconBtn} onPress={() => navigation.goBack()}>
            <MaterialIcons name="keyboard-backspace" size={25} color="#46D7FF" />
          </PressableScale>
        </View>

        <View style={styles.summaryGrid}>
          {renderCampoResumo('music-circle', 'Titulo', titulo, setTitulo, 'Titulo do repertorio')}
          {renderCampoResumo('calendar-month', 'Data', data, setData, 'Data')}
          {renderCampoResumo('account-tie', 'Responsavel', responsavel, setResponsavel, 'Responsavel')}
        </View>

        <View style={styles.sectionHeader}>
          <Text style={styles.sectionTitle}>Musicas</Text>
          <Text style={styles.sectionCount}>{musicas.length}</Text>
        </View>

        <View style={styles.musicList}>
          {musicas.map((item: any, index: number) => {
            const colors = cardGradients[index % cardGradients.length];
            return (
              <LinearGradient key={`${item.nome}-${index}`} colors={['#FFB84D', '#43E97B', '#46D7FF']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.musicBorder}>
                <LinearGradient colors={colors} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.musicCard}>
                  <View style={styles.cardGlow} />
                  <View style={styles.musicTopRow}>
                    <View style={styles.musicNumber}>
                      <Text style={styles.musicNumberText}>{index + 1}</Text>
                    </View>
                    <View style={styles.musicMain}>
                      <Text style={styles.musicLabel}>Musica</Text>
                      {editando ? (
                        <TextInput
                          style={styles.musicInput}
                          value={item.nome}
                          onChangeText={text => handleChangeMusica(index, 'nome', text)}
                          placeholder="Nome da musica"
                          placeholderTextColor="#BFD7FF"
                        />
                      ) : (
                        <Text style={styles.musicTitle}>{item.nome}</Text>
                      )}
                    </View>
                    <View style={styles.tomBadge}>
                      <Text style={styles.tomBadgeLabel}>Tom</Text>
                      <Text style={styles.tomBadgeValue}>{editando ? allTons[tomIndexes[index]] : item.tom}</Text>
                    </View>
                  </View>

                  {editando ? (
                    <View style={styles.editArea}>
                      <View style={styles.tomStepper}>
                        <TouchableOpacity
                          style={styles.stepButton}
                          onPress={() => {
                            const newIdx = (tomIndexes[index] - 1 + allTons.length) % allTons.length;
                            handleChangeMusica(index, 'tom', allTons[newIdx]);
                          }}
                        >
                          <MaterialIcons name="chevron-left" size={25} color="#67E8F9" />
                        </TouchableOpacity>
                        <Text style={styles.tomStepperValue}>{allTons[tomIndexes[index]]}</Text>
                        <TouchableOpacity
                          style={styles.stepButton}
                          onPress={() => {
                            const newIdx = (tomIndexes[index] + 1) % allTons.length;
                            handleChangeMusica(index, 'tom', allTons[newIdx]);
                          }}
                        >
                          <MaterialIcons name="chevron-right" size={25} color="#67E8F9" />
                        </TouchableOpacity>
                      </View>
                      <TextInput
                        style={styles.linkInput}
                        value={item.linkLetra}
                        onChangeText={text => handleChangeMusica(index, 'linkLetra', text)}
                        placeholder="Link da letra"
                        placeholderTextColor="#BFD7FF"
                        autoCapitalize="none"
                        autoCorrect={false}
                        keyboardType="url"
                      />
                      <TextInput
                        style={styles.linkInput}
                        value={item.linkYoutube}
                        onChangeText={text => handleChangeMusica(index, 'linkYoutube', text)}
                        placeholder="Link do YouTube"
                        placeholderTextColor="#BFD7FF"
                        autoCapitalize="none"
                        autoCorrect={false}
                        keyboardType="url"
                      />
                      <TouchableOpacity
                        style={styles.deleteMusicButton}
                        onPress={() => handleExcluirMusica(index)}
                        activeOpacity={0.84}
                      >
                        <MaterialIcons name="delete-outline" size={20} color="#FFE5E5" />
                        <Text style={styles.deleteMusicButtonText}>Excluir musica</Text>
                      </TouchableOpacity>
                    </View>
                  ) : (
                    <View style={styles.linkRow}>
                      <TouchableOpacity style={[styles.linkButton, !item.linkLetra && styles.linkButtonDisabled]} onPress={() => abrirLink(item.linkLetra)} disabled={!item.linkLetra}>
                        <MaterialCommunityIcons name="file-document-outline" size={18} color={item.linkLetra ? '#111827' : '#6B7280'} />
                        <Text style={[styles.linkButtonText, !item.linkLetra && styles.linkButtonTextDisabled]}>Letra</Text>
                      </TouchableOpacity>
                      <TouchableOpacity style={[styles.linkButton, styles.youtubeButton, !item.linkYoutube && styles.linkButtonDisabled]} onPress={() => abrirLink(item.linkYoutube)} disabled={!item.linkYoutube}>
                        <MaterialIcons name="play-arrow" size={20} color={item.linkYoutube ? '#fff' : '#6B7280'} />
                        <Text style={[styles.youtubeButtonText, !item.linkYoutube && styles.linkButtonTextDisabled]}>YouTube</Text>
                      </TouchableOpacity>
                    </View>
                  )}
                </LinearGradient>
              </LinearGradient>
            );
          })}
        </View>

        {editando && (
          <LinearGradient colors={['#FFB84D', '#43E97B', '#46D7FF']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.addMusicBorder}>
            <LinearGradient colors={['#172044', '#211B3D']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.addMusicCard}>
              <Text style={styles.addMusicTitle}>Adicionar nova musica</Text>
              <TextInput style={styles.input} placeholder="Nome da musica" value={novaNome} onChangeText={setNovaNome} placeholderTextColor="#BFD7FF" />
              <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.tonesScroll}>
                {allTons.map(item => (
                  <TouchableOpacity key={item} style={[styles.tomOption, novaTom === item && styles.tomOptionSelected]} onPress={() => setNovaTom(item)}>
                    <Text style={[styles.tomOptionText, novaTom === item && styles.tomOptionTextSelected]}>{item}</Text>
                  </TouchableOpacity>
                ))}
              </ScrollView>
              <TextInput style={styles.input} placeholder="Link da letra" value={novaLinkLetra} onChangeText={setNovaLinkLetra} placeholderTextColor="#BFD7FF" autoCapitalize="none" autoCorrect={false} keyboardType="url" />
              <TextInput style={styles.input} placeholder="Link do YouTube" value={novaLinkYoutube} onChangeText={setNovaLinkYoutube} placeholderTextColor="#BFD7FF" autoCapitalize="none" autoCorrect={false} keyboardType="url" />
              <GradientButton onPress={handleAdicionarMusica} variant="success" style={{ marginTop: 8 }}>Adicionar Musica</GradientButton>
            </LinearGradient>
          </LinearGradient>
        )}

        <View style={styles.buttonRow}>
          {editando ? (
            <GradientButton style={{ flex: 1, marginRight: 8 }} onPress={handleSalvar} disabled={salvando}>
              {salvando ? 'Salvando...' : 'Salvar'}
            </GradientButton>
          ) : (
            <GradientButton style={{ flex: 1, marginRight: 8 }} onPress={() => setEditando(true)}>
              Editar
            </GradientButton>
          )}
          <GradientButton style={{ flex: 1, marginLeft: 8 }} onPress={() => navigation.goBack()} variant="secondary">
            Voltar
          </GradientButton>
        </View>
      </ScrollView>
    </LinearGradient>
  );
};

